/** Breakpoints for responsive design that can be used in hooks
 *  All designs are based on 'small', use 'medium' for desktop modifications.
 * Only use the other breakpoints if absolutely necessary.
 * @important Make sure to keep these in sync with the breakpoints in the CSS file (src\constants\breakpoints.less)
 * @important useIsMobile() hook uses these breakpoints to determine if the device is mobile or not, make sure to update the hook if you change these breakpoints
 */
export const breakpoints = {
  /** Extra small devices - Small phones (320px) */
  xsmall: "(min-width: 20rem)",

  /** Default for all designs \
   * Small devices - Phones (360px)
   */
  small: "(min-width: 22.5rem)",

  /** Main breakpoint for desktop modification \
   * Medium devices - Tablets, laptops (768px)
   */
  medium: "(min-width: 48rem)",

  /** Large devices - Desktops (1440px) */
  large: "(min-width: 90rem)",

  /** Extra large devices - Ultra wide screens (3200px) */
  xlarge: "(min-width: 200rem)",

  /** Internet Explorere only */
  ieOnly: "all and (-ms-high-contrast:none)",
};
