import ServiceHelper from "./service-helper";

type WaitingRoomResponse = {
  key: string | null;
  placeInQueue: number | null;
  yourTurn: boolean | null;
  secondsLeft: number | null;
  maxSeconds: number | null;
  message: string | null;
};

class WaitingRoomService {
  waitingRoomUrl: string;
  company: string;
  additionalOptions: Partial<RequestInit>;

  constructor() {
    this.waitingRoomUrl = "https://prs-cdp-prod-waitingroom-webapp.azurewebsites.net/api";
    this.company = process.env.GATSBY_MY_PARKS_COMPANY || "TestGLT";

    this.additionalOptions = {
      headers: {
        "X-Company": this.company,
      },
    };
  }

  postWaitingRoomTicket(): Promise<{ response: WaitingRoomResponse }> {
    return ServiceHelper.fetchPost("/waiting-room-tickets", {}, this.additionalOptions, this.waitingRoomUrl);
  }

  getWaitingRoomTicket(key: string): Promise<{ response: WaitingRoomResponse }> {
    return ServiceHelper.fetchGet(`/waiting-room-tickets/${key}`, this.additionalOptions, this.waitingRoomUrl);
  }

  deleteWaitingRoomTicket(key: string) {
    return ServiceHelper.fetchDelete(`/waiting-room-tickets/${key}`, {}, this.additionalOptions, this.waitingRoomUrl);
  }
}

const helper = new WaitingRoomService();
export default helper;
