import { useShopServiceCartContext } from "@/core/contexts";
import { usePayment, useFinalizeKlarnaPayment, useCart, usePaymentStyles } from "@/core/hooks";
import { PaymentState } from "@parksandresorts/webapiproxy-types";
import { useCallback, useEffect, useRef, useState } from "react";
import { CheckoutService, ICheckoutService } from "@/core/services/checkout-service";
import styles from "./shop-service-order-confirmation.module.less";
import { KlarnaCheckout } from "@/core/components/modules/klarna-checkout/klarna-checkout";
import { useTranslation } from "react-i18next";
import { paymentToPurchaseGTMEvent, trackEcommerceEvent } from "@/core/helpers/gtm-helper";
import { EventAggregator, LocalStorageHelper, exhaustiveCheck } from "@/core/helpers";
import { WaitingRoomService } from "@/core/services";
import AuthAware from "../../hocs/auth-aware/auth-aware";
import Card from "@/core/components/primitives/card/card";
import { usePollForOrderInAuth } from "@/core/hooks/use-poll-for-order";
import { CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { NetsCheckoutIframe } from "@/core/components/modules/nets-checkout/nets-checkout";
import { Language } from "@/core/labels/i18n";
import { useAuthState } from "@/core/auth";

export type ShopServiceOrderConfirmationProps = {
  cartId: string;
  /**
   * This is a required property, even though it is only used in a Klarna-context, to make sure we
   * don't accidentally break the Klarna flow. When not used in a Klarna-context, could be set to
   * any string, e.g. an empty string.
   */
  klarnaOrderId: string;
  checkoutService?: ICheckoutService;
};

export const ShopServiceOrderConfirmation = AuthAware<ShopServiceOrderConfirmationProps>(function InnerConfirmation({
  cartId,
  klarnaOrderId,
  checkoutService = CheckoutService,
}) {
  const { t } = useTranslation();

  const { data: payment } = usePayment(cartId, checkoutService);
  const { forgetCartIfActive } = useShopServiceCartContext();

  useEffect(() => {
    if (cartId) {
      forgetCartIfActive(cartId);
    }
  }, [cartId, forgetCartIfActive]);

  // If the payment has been done within a WaitingRoom-HOC we need to leave the queue
  useEffect(() => {
    const leaveQueueIfNeeded = () => {
      const waitingRoomKey = LocalStorageHelper.getItem("waitingRoomKey");
      if (waitingRoomKey) {
        WaitingRoomService.deleteWaitingRoomTicket(waitingRoomKey);
      }
    };
    leaveQueueIfNeeded();
  }, []);

  const isFetchingLatestOrder = usePollForOrderInAuth(payment?.orderId);

  const component = () => {
    const provider = payment?.paymentProvider;
    switch (provider) {
      case undefined:
      case null:
        // render nothing while loading
        return null;
      case "Klarna":
        return (
          <KlarnaOrderConfirmation cartId={cartId} klarnaOrderId={klarnaOrderId} checkoutService={checkoutService} />
        );
      case "ZeroAmount":
        // No need to render anything special for zero amount payments
        return null;
      case "Nets":
        return <NetsOrderConfirmation cartId={cartId} checkoutService={checkoutService} />;
      default:
        return exhaustiveCheck(provider);
    }
  };

  return (
    <div className={styles.wrapper}>
      {isFetchingLatestOrder && (
        <Card className={styles.loadingCard}>
          <p className="heading-l">{t("orderConfirmationCompletingPurchase")}</p>
          <CheckoutLoading />
        </Card>
      )}
      {component()}
    </div>
  );
});

export function KlarnaOrderConfirmation({
  cartId,
  klarnaOrderId,
  checkoutService = CheckoutService,
}: ShopServiceOrderConfirmationProps) {
  const { t } = useTranslation();
  const { data: payment } = usePayment(cartId, checkoutService);

  const doTrack = useDoTrackGTMPurchaseEvent(cartId, checkoutService);

  const { mutateAsync: doFinalize, error: finalizedPaymentError } = useFinalizeKlarnaPayment(
    cartId,
    klarnaOrderId,
    checkoutService,
  );

  const shouldFinalize = !!payment && payment.paymentState !== PaymentState.PAID;
  useEffect(() => {
    if (shouldFinalize) {
      doFinalize().then(doTrack);
    }
  }, [shouldFinalize, doFinalize, doTrack]);

  return (
    <>
      {finalizedPaymentError && <p>{t("checkoutErrorMessage")}</p>}
      {payment?.paymentState === PaymentState.PAID && (
        <KlarnaCheckout cartId={cartId} checkoutService={checkoutService} />
      )}
    </>
  );
}

// This is a local helper hook to make sure we wait for everything to load before we track the GTM event.
const useDoTrackGTMPurchaseEvent = (cartId: string, checkoutService?: ICheckoutService) => {
  const [shouldTrack, setShouldTrack] = useState(false);
  const { data: cart } = useCart(cartId, checkoutService);
  const { data: payment } = usePayment(cartId, checkoutService);
  const authState = useAuthState();

  const hasTracked = useRef(false);

  useEffect(() => {
    if (!authState.sessionFetched) {
      // Don't track anything until we know the auth state
      return;
    }
    if (!hasTracked.current && shouldTrack && cart && payment) {
      trackEcommerceEvent(paymentToPurchaseGTMEvent(cart, payment));

      EventAggregator.publish("trackEvent", {
        category: "Purchase",
        action: "IsLoggedIn",
        label: authState.isLoggedIn ? "Yes" : "No",
      });
      hasTracked.current = true;
    }
  }, [shouldTrack, cart, payment, authState.sessionFetched, authState.isLoggedIn]);

  return useCallback(() => setShouldTrack(true), []);
};

export function NetsOrderConfirmation({
  cartId,
  checkoutService = CheckoutService,
}: Omit<ShopServiceOrderConfirmationProps, "klarnaOrderId">) {
  const { i18n } = useTranslation();
  const locale = i18n.language as Language;
  const { component: stylingComponent, paymentStyling } = usePaymentStyles("Nets");
  return (
    <>
      {stylingComponent}
      <NetsCheckoutIframe
        cartId={cartId}
        checkoutService={checkoutService}
        theme={paymentStyling?.nets}
        locale={locale}
      />
    </>
  );
}
