// Purchased whole album
export const Primary: Story = {
  args: {
    resetQueryKeys: [
      ["cart-items", CART_ID],
      ["klarna-payment", CART_ID],
      ["finalize-payment", CART_ID],
    ],
    cartId: CART_ID,
    orderId: "5678",
    getAlbumSlug: (albumId: string) => {
      return `foto/album/${albumId}`;
    },
    startPageSlug: "/foto/start",
    checkoutService: checkoutServiceStub,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await waitFor(() => {
      expect(
        canvas.getByText(
          "Du har köpt hela albumet! 🎉 Alla bilder/videor i albumet kommer snart låsas upp. Alla bilder & videor som läggs till senare låses upp automatiskt – kom ihåg att ladda ner dem också.",
        ),
      ).toBeInTheDocument(); // rideMediaConfirmationPageParagraphBoughtAlbum
      expect(canvas.getByText("Gå till album")).toBeInTheDocument(); // Go to album button
    });
  },
};

